    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // 1. Admissible domain: caller must be 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9 and _tos length > 0
