    function boundUints(uint[] memory arr) internal pure {
        for (uint i = 0; i < arr.length; i++) {
            assembly {
                mstore(add(arr, add(0x20, mul(i, 0x20))), mod(mload(add(arr, add(0x20, mul(i, 0x20)))), 100000000000000000000000))
            }
        }
    }
}

