pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Restrict domain to avoid the `vm.assume` rejection due to too many inputs.
        // Keep arrays non-empty and lengths matching, and bound v values to avoid overflow in mul_uint256.
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i=0; i<v.length; i++) {
            bound(v[i], 1, type(uint256).max / 1000000000000000000);
        }

        // Prank a non-owner sender: the reference C must reject, the buggy M must succeed.
        // But the previously tried assertion on success flag failed.
        // Instead we assert a more subtle invariant: the external call always returns false
        // because caddress (EOA) has no code, and that result is visible in the emitted event?
        // There is no event. So we wrap in try/catch and assert that for any sender (including non-owner),
        // when called from a non-owner, the reference REVERTS (output false in catch),
        // but the buggy M does NOT revert (output true).
        // This is exactly what was tried earlier and rejected, but we now fuzz the arrays more carefully
        // to avoid the `vm.assume` limit: we restrict array length to <= 8 to reduce search space.
        vm.assume(_tos.length <= 8);

        vm.prank(address(0x123)); // any non-owner
        bool ok;
        try c.transfer(_tos, v) returns (bool success) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference should revert (ok == false), the buggy should succeed (ok == true).
        // So the invariant: ok must always be false for the reference.
        // But that invariant fails on buggy.
        // However, we need a single assertTrue that holds for reference and fails for buggy.
        // Since reference always reverts, "ok == false" is true for reference, false for buggy.
        assertTrue(!ok);
    }
}

